/* B2 · topics 6–10 (format: see a2-part1.js). */
module.exports = [
  { title: 'Health systems', lessons: [
    { t: ['Healthcare vocabulary', 'Sog‘liqni saqlash lug‘ati'],
      obj: ['Sog‘liqni saqlash tizimi va tibbiy xizmat atamalarini aniq qo‘llaysiz.', 'You will use healthcare system and medical service terms accurately.'],
      ex: ['Atamalar: GP / family doctor, specialist, referral (yo‘llanma), waiting list (navbat), outpatient / inpatient (ambulator / statsionar), diagnosis (tashxis), treatment, surgery (jarrohlik), chronic (surunkali) vs acute (o‘tkir), side effects. Tizim: public vs private healthcare, universal coverage, health insurance.\nMajhul: Patients are referred to specialists. A diagnosis was made after several tests. Sabab: Long waiting lists result from a shortage of doctors. Misol: such as, including.', 'Terms: GP / family doctor, specialist, referral, waiting list, outpatient / inpatient, diagnosis, treatment, surgery, chronic vs acute, side effects. System: public vs private healthcare, universal coverage, health insurance.\nPassive: Patients are referred to specialists. A diagnosis was made after several tests. Cause: Long waiting lists result from a shortage of doctors. Examples: such as, including.'],
      eg: [['Patients are referred to specialists by their GP.', 'Bemorlar umumiy shifokor tomonidan mutaxassisga yo‘llanadi.'], ['Chronic diseases require long-term treatment.', 'Surunkali kasalliklar uzoq muddatli davolashni talab qiladi.'], ['Long waiting lists result from a shortage of doctors.', 'Uzoq navbatlar shifokorlar yetishmasligidan kelib chiqadi.'], ['Some drugs have unpleasant side effects.', 'Ba’zi dori vositalarining yoqimsiz yon ta’sirlari bor.']],
      w: [['diagnosis', 'tashxis', 'диагноз', 'noun', 'The diagnosis was confirmed by tests.', 'Tashxis tahlillar bilan tasdiqlandi.', 'ˌdaɪəɡˈnəʊsɪs'], ['referral', 'yo‘llanma', 'направление', 'noun', 'You need a referral from your GP.', 'Sizga umumiy shifokordan yo‘llanma kerak.', 'rɪˈfɜːrəl'], ['chronic', 'surunkali', 'хронический', 'adjective', 'He suffers from chronic pain.', 'U surunkali og‘riqdan azob chekadi.', 'ˈkrɒnɪk'], ['surgery', 'jarrohlik', 'операция', 'noun', 'She needs surgery on her knee.', 'Unga tizza jarrohligi kerak.', 'ˈsɜːdʒəri'], ['outpatient', 'ambulator bemor', 'амбулаторный пациент', 'noun', 'Outpatients go home the same day.', 'Ambulator bemorlar o‘sha kuni uyga ketadi.', 'ˈaʊtpeɪʃnt'], ['side effect', 'yon ta’sir', 'побочный эффект', 'noun', 'Drowsiness is a common side effect.', 'Uyquchanlik keng tarqalgan yon ta’sir.', 'saɪd ɪˈfekt']],
      g: [['Patients ___ to specialists by their GP.', 'are referred', 'refer', 'are referring', 'Majhul.'], ['Long waiting lists ___ from a shortage of doctors.', 'result', 'results to', 'resulting', '“result from” — … dan kelib chiqadi.']],
      dlg: ['Patient: My GP gave me a referral to a specialist. Receptionist: The waiting list is about six weeks. Patient: That is a long time. Receptionist: Chronic cases are usually seen first. Patient: Will the treatment have side effects? Receptionist: The doctor will explain everything after the diagnosis.', 'How long is the waiting list?', 'About six weeks', 'Two days', 'One year', 'She says “about six weeks”.'],
      rd: ['Healthcare systems differ in how they are financed. In some countries, public healthcare is funded by taxes and offers universal coverage, so every citizen can see a GP free of charge. In others, people rely on private insurance, which can lead to inequality of access. All systems face challenges, notably ageing populations, rising costs and shortages of nurses and doctors. As a result, waiting lists for non-urgent surgery can be long, even in wealthy countries.', ['What do all systems face?', 'Ageing populations, rising costs and shortages', 'Too many doctors', 'No patients'], ['Universal coverage means only the rich can see a GP.', 'False'], ['Private insurance is cheaper everywhere.', 'Not Given']],
      wr: ['Describe how the healthcare system works in your country (10 sentences), using passive forms and healthcare vocabulary.', 'are referred|waiting list|treatment|result from', 70, 'In my country basic healthcare is provided by the state. Patients are first examined by a family doctor. If necessary, they are referred to a specialist. Long waiting lists result from a shortage of doctors. Chronic diseases require regular treatment. Private clinics are faster but more expensive.'],
      sp: ['Explain what happens when you visit a GP in your country.', 'First the GP examines the patient and makes a diagnosis. If necessary, the patient is referred to a specialist.'],
      ts: [['A long-lasting illness:', 'chronic', 'acute', 'inpatient'], ['“Tashxis” in English:', 'diagnosis', 'referral', 'surgery'], ['The medicine had unpleasant ___.', 'side effects', 'outpatients', 'waiting']] },
    { t: ['Public health', 'Jamoat salomatligi'],
      obj: ['Jamoat salomatligi kampaniyalari va profilaktikani tahlil qilasiz.', 'You will analyse public health campaigns and prevention.'],
      ex: ['Jamoat salomatligi: vaccination, epidemic / pandemic, prevention (profilaktika), outbreak (avj olish), immunity, awareness campaign, sanitation, life expectancy (umr davomiyligi), obesity. Qiyos: Life expectancy has risen thanks to… Yaxshilanish: has increased by, has declined steadily.\nBo‘lishsizlik: Had it not been for vaccines, millions would have died. (Third conditional.) Inversion: Had it not been for…; Should you feel unwell, … Maqsad: in order to / so as to / so that + modal.', 'Public health: vaccination, epidemic / pandemic, prevention, outbreak, immunity, awareness campaign, sanitation, life expectancy, obesity. Change: Life expectancy has risen thanks to… has increased by, has declined steadily.\nThird conditional: Had it not been for vaccines, millions would have died. Inversion: Had it not been for…; Should you feel unwell, … Purpose: in order to / so as to / so that + modal.'],
      eg: [['Had it not been for vaccines, millions would have died.', 'Vaksinalar bo‘lmaganida, millionlab odam o‘lgan bo‘lardi.'], ['Life expectancy has risen thanks to better sanitation.', 'Yaxshilangan sanitariya tufayli umr davomiyligi oshdi.'], ['Campaigns aim to raise awareness of obesity.', 'Kampaniyalar semirish haqida xabardorlikni oshirishga qaratilgan.'], ['Vaccination provides immunity against the disease.', 'Vaksinatsiya kasallikka qarshi immunitet beradi.']],
      w: [['vaccination', 'emlash', 'вакцинация', 'noun', 'Vaccination protects children.', 'Emlash bolalarni himoya qiladi.', 'ˌvæksɪˈneɪʃn'], ['outbreak', 'avj olish', 'вспышка', 'noun', 'An outbreak of flu began in March.', 'Gripp avj olishi martda boshlandi.', 'ˈaʊtbreɪk'], ['immunity', 'immunitet', 'иммунитет', 'noun', 'Immunity develops after infection.', 'Immunitet kasallikdan keyin paydo bo‘ladi.', 'ɪˈmjuːnəti'], ['sanitation', 'sanitariya', 'санитария', 'noun', 'Poor sanitation spreads disease.', 'Yomon sanitariya kasallik tarqatadi.', 'ˌsænɪˈteɪʃn'], ['life expectancy', 'umr davomiyligi', 'ожидаемая продолжительность жизни', 'noun', 'Life expectancy is increasing.', 'Umr davomiyligi oshmoqda.', 'laɪf ɪkˈspektənsi'], ['obesity', 'semirish', 'ожирение', 'noun', 'Obesity is a growing problem.', 'Semirish kuchayib borayotgan muammo.', 'əʊˈbiːsəti']],
      g: [['___ it not been for vaccines, millions would have died.', 'Had', 'If', 'Have', 'Third conditional inversiya.'], ['Campaigns aim ___ raise awareness.', 'to', 'for', 'at to', '“aim to”.']],
      dlg: ['Doctor: Life expectancy has risen thanks to better sanitation and vaccination. Student: Has the number of outbreaks fallen? Doctor: Yes. Had it not been for vaccines, many diseases would have spread widely. Student: What about obesity? Doctor: It is increasing, so awareness campaigns are essential.', 'What is increasing, according to the doctor?', 'Obesity', 'Outbreaks', 'Illiteracy', 'He says “It is increasing” about obesity.'],
      rd: ['One of the greatest achievements of modern medicine is the rise in life expectancy. In many countries it has increased by around thirty years since 1900, thanks largely to clean water, sanitation and vaccination programmes. Smallpox, which once killed millions, has been eradicated, and polio has nearly disappeared. Today the main threats are lifestyle-related illnesses such as obesity and diabetes, which public health campaigns try to tackle by encouraging exercise and healthier diets.', ['What are the main threats today?', 'Lifestyle-related illnesses', 'Smallpox', 'Lack of doctors'], ['Smallpox still kills millions.', 'False'], ['Life expectancy is highest in Japan.', 'Not Given']],
      wr: ['Write an essay paragraph (10 sentences) on how vaccination and sanitation have improved public health; include a third conditional.', 'had it not been|would have|life expectancy|thanks to', 80, 'Public health has improved dramatically in the last century. Life expectancy has risen thanks to vaccination and clean water. Had it not been for vaccines, many diseases would have spread widely. Smallpox has been eradicated. Today campaigns focus on obesity, which is increasing.'],
      sp: ['Say how vaccination has changed our lives.', 'Had it not been for vaccines, many people would have died. Life expectancy has risen thanks to them.'],
      ts: [['Protection against a disease:', 'immunity', 'obesity', 'outbreak'], ['“Emlash” in English:', 'vaccination', 'sanitation', 'prevention'], ['___ you feel unwell, see a doctor.', 'Should', 'Would', 'Had']] },
    { t: ['Mental health', 'Ruhiy salomatlik'],
      obj: ['Ruhiy salomatlik masalalarini sezgirlik bilan muhokama qilasiz.', 'You will discuss mental health issues sensitively.'],
      ex: ['Ruhiy salomatlik: depression, anxiety, stigma (tamg‘a), therapy, counselling, support network, coping mechanism, resilience (chidamlilik), seek help. Sezgir til: People who suffer from…, rather than “mad”; Avoid stereotypes. Maslahat: It is vital that + asosiy shakl: It is vital that people seek help early.\nKengaytirilgan tuzilma: Not only … but also; the fact that…; What matters is…; It is not until… that… (faqat shundan keyin). Fe’l shakllari: encourage somebody to, urge, advise against + -ing.', 'Mental health: depression, anxiety, stigma, therapy, counselling, support network, coping mechanism, resilience, seek help. Sensitive language: People who suffer from… rather than “mad”; avoid stereotypes. Advice: It is vital that + base verb: It is vital that people seek help early.\nExtended structures: Not only … but also; the fact that…; What matters is…; It is not until… that… Verb patterns: encourage somebody to, urge, advise against + -ing.'],
      eg: [['It is vital that people seek help early.', 'Odamlar erta yordam so‘rashi juda muhim.'], ['The stigma around depression discourages many from speaking.', 'Depressiya atrofidagi tamg‘a ko‘pchilikni gapirishdan to‘sadi.'], ['It was not until he talked to a counsellor that he felt better.', 'Maslahatchi bilan gaplashgandan keyingina u o‘zini yaxshi his qildi.'], ['Resilience helps people cope with stress.', 'Chidamlilik odamlarga stress bilan kurashishga yordam beradi.']],
      w: [['stigma', 'tamg‘a (ijtimoiy)', 'стигма', 'noun', 'Stigma prevents people from seeking help.', 'Tamg‘a odamlarni yordam so‘rashdan to‘sadi.', 'ˈstɪɡmə'], ['counselling', 'maslahat berish (psixolog)', 'консультирование', 'noun', 'Counselling helped her recover.', 'Maslahat unga tuzalishga yordam berdi.', 'ˈkaʊnsəlɪŋ'], ['resilience', 'chidamlilik', 'устойчивость', 'noun', 'Resilience grows with experience.', 'Chidamlilik tajriba bilan o‘sadi.', 'rɪˈzɪliəns'], ['anxiety', 'xavotir buzilishi', 'тревожность', 'noun', 'Anxiety affects sleep.', 'Xavotir uyquga ta’sir qiladi.', 'æŋˈzaɪəti'], ['cope with', 'kurashmoq, uddalamoq', 'справляться', 'phrasal verb', 'How do you cope with stress?', 'Stress bilan qanday kurashasiz?', 'kəʊp wɪð'], ['support network', 'qo‘llab-quvvatlovchi doira', 'круг поддержки', 'noun', 'A support network is essential.', 'Qo‘llab-quvvatlovchi doira zarur.', 'səˈpɔːt ˈnetwɜːk']],
      g: [['It is vital that people ___ help early.', 'seek', 'seeks', 'sought', 'Subjunktiv: that + asosiy shakl.'], ['It was not ___ he talked to a counsellor that he felt better.', 'until', 'since', 'before', '“not until … that”.']],
      dlg: ['Counsellor: What brings you here today? Client: I feel anxious all the time. I was afraid to ask for help because of the stigma. Counsellor: It is vital that you took this step. Client: I didn’t talk to anyone until last week. Counsellor: Let’s think about a support network and some coping strategies.', 'What stopped the client from asking for help?', 'The stigma', 'The price', 'A lack of time', 'The client says “because of the stigma”.'],
      rd: ['Mental health problems are among the most common illnesses worldwide, yet many sufferers wait years before seeking help. One reason is stigma: the fear of being judged or treated differently. Experts stress that depression and anxiety are medical conditions, not personal weaknesses, and that they respond well to treatment such as therapy or medication. Building resilience, maintaining a support network and talking openly about problems can help people cope, and it is vital that schools and workplaces encourage such openness.', ['Why do many sufferers wait years?', 'Stigma', 'Lack of illness', 'Free treatment'], ['Experts see depression as a personal weakness.', 'False'], ['Therapy is always expensive.', 'Not Given']],
      wr: ['Write a short article (10–12 sentences) encouraging people to talk about mental health; use “It is vital that…” and “not until”.', 'it is vital that|stigma|support|not until', 80, 'Mental health is as important as physical health. It is vital that people seek help early. Unfortunately, stigma prevents many from speaking. It was not until I talked to a friend that I understood how important support is. Resilience grows when people share their problems.'],
      sp: ['Give advice to a friend who feels very stressed.', 'It is vital that you talk to someone. You should build a support network and rest enough.'],
      ts: [['Ability to recover from difficulties:', 'resilience', 'stigma', 'anxiety'], ['“Kurashmoq, uddalamoq” (phrasal):', 'cope with', 'look up', 'turn on'], ['It is important that he ___ a doctor.', 'see', 'sees', 'saw']] },
    { t: ['A health debate', 'Sog‘liq haqida munozara'],
      obj: ['Sog‘liq mavzusida rasmiy munozarada o‘z tomoningizni himoya qilasiz.', 'You will defend your side in a formal debate on a health topic.'],
      ex: ['Munozara tuzilmasi: Opening (ochilish) → Arguments (dalillar) → Rebuttal (rad etish) → Closing (yakun). Iboralar: Ladies and gentlemen, I stand before you to argue that… Our first argument is… Opponents claim that…, but this overlooks… Evidence shows… In conclusion, we urge you to support the motion (taklif).\nMavzu: Should sugary drinks be taxed? Should junk food ads be banned? Majhul va shartli: If sugar were taxed, consumption would fall. Kuchaytirish: undoubtedly, clearly, without a doubt, a compelling argument.', 'Debate structure: Opening → Arguments → Rebuttal → Closing. Phrases: Ladies and gentlemen, I stand before you to argue that… Our first argument is… Opponents claim that…, but this overlooks… Evidence shows… In conclusion, we urge you to support the motion.\nTopic: Should sugary drinks be taxed? Should junk food ads be banned? Conditional: If sugar were taxed, consumption would fall. Emphasis: undoubtedly, clearly, without a doubt, a compelling argument.'],
      eg: [['I stand before you to argue that sugary drinks should be taxed.', 'Shirin ichimliklarga soliq solinishi kerakligini isbotlash uchun turibman.'], ['Opponents claim that taxes are unfair, but this overlooks the cost of obesity.', 'Raqiblar soliq adolatsiz deydi, ammo bu semirish narxini e’tiborsiz qoldiradi.'], ['If sugar were taxed, consumption would fall.', 'Shakarga soliq solinsa, iste’mol kamayardi.'], ['We urge you to support the motion.', 'Takliflarni qo‘llab-quvvatlashga chaqiramiz.']],
      w: [['motion', 'taklif (munozarada)', 'тезис', 'noun', 'The motion was rejected.', 'Taklif rad etildi.', 'ˈməʊʃn'], ['rebuttal', 'rad javobi', 'опровержение', 'noun', 'Her rebuttal was convincing.', 'Uning rad javobi ishonarli edi.', 'rɪˈbʌtl'], ['overlook', 'e’tiborsiz qoldirmoq', 'упускать из виду', 'verb', 'This argument overlooks the cost.', 'Bu dalil narxni e’tiborsiz qoldiradi.', 'ˌəʊvəˈlʊk'], ['compelling', 'ishonarli (kuchli)', 'убедительный', 'adjective', 'It is a compelling argument.', 'Bu ishonarli dalil.', 'kəmˈpelɪŋ'], ['urge', 'qat’iy chaqirmoq', 'настоятельно призывать', 'verb', 'We urge you to vote.', 'Ovoz berishga chaqiramiz.', 'ɜːdʒ'], ['advocate', 'himoya qilmoq', 'выступать за', 'verb', 'They advocate a ban on advertising.', 'Ular reklamani taqiqlashni yoqlaydi.', 'ˈædvəkeɪt']],
      g: [['If sugar ___ taxed, consumption would fall.', 'were', 'is', 'would be', 'Second conditional.'], ['We urge you ___ support the motion.', 'to', 'for', 'that', '“urge somebody to”.']],
      dlg: ['Chair: The motion is that sugary drinks should be taxed. Speaker A: I stand before you to argue that taxation reduces consumption. Speaker B: Opponents claim that taxes hurt the poor, but this overlooks the cost of obesity to everyone. Chair: Is there a rebuttal? Speaker B: Evidence from several countries shows a clear fall in sales.', 'What does the evidence show, according to Speaker B?', 'A clear fall in sales', 'Higher consumption', 'No change', 'B says “a clear fall in sales”.'],
      rd: ['At last week’s school debate, two teams argued about whether junk food advertising should be banned. The proposing team presented evidence that children exposed to such advertisements consume more sugar and fat. The opposing team claimed that a ban would limit freedom and harm advertising jobs, but the proposers replied that protecting children outweighs these concerns. After a lively rebuttal round, the judges awarded the victory to the proposers because of their clear structure and strong evidence.', ['Why did the proposers win?', 'Clear structure and strong evidence', 'They spoke longer', 'They had more members'], ['The opposing team supported the ban.', 'False'], ['The debate took place in a stadium.', 'Not Given']],
      wr: ['Write a debate speech (200 words) for or against: “Junk food advertising should be banned.” Include opening, two arguments, rebuttal and closing.', 'i stand before you|opponents claim|evidence shows|in conclusion', 130, 'Ladies and gentlemen, I stand before you to argue that junk food advertising should be banned. Our first argument is that children are easily influenced. Evidence shows that those exposed to such advertisements eat more sugar. Opponents claim that a ban limits freedom, but this overlooks the cost of obesity. In conclusion, we urge you to support the motion.'],
      sp: ['Give a one-minute opening speech for or against a sugar tax.', 'I stand before you to argue that a sugar tax is necessary. Evidence shows that it reduces consumption.'],
      ts: [['A formal proposal in a debate:', 'motion', 'rebuttal', 'stigma'], ['“Rad javobi” in English:', 'rebuttal', 'motion', 'advocate'], ['Opponents ___ that a tax is unfair.', 'claim', 'claims to', 'claiming']] },
  ], exam: [['___ it not been for the vaccine, many would have died.', 'Had', 'Have', 'Was', 'grammar'], ['It is vital that students ___ enough sleep.', 'get', 'gets', 'got', 'grammar'], ['“Chidamlilik” in English:', 'resilience', 'stigma', 'diagnosis', 'vocabulary']] },

  { title: 'Media and advertising', lessons: [
    { t: ['News and the media', 'Yangiliklar va OAV'],
      obj: ['OAV turlari, manbalar va xabar berish uslublarini farqlaysiz.', 'You will distinguish types of media, sources and styles of reporting.'],
      ex: ['OAV: broadcast media (televideniye, radio), print media (gazeta), online media, headline (sarlavha), journalist, editor, source, bias, coverage (yoritish), press freedom. Xabar bergan fe’l: claim, state, reveal, allege (da’vo qilmoq).\nBayon qilingan nutq: He said that he had seen the accident. Reporting verbs: He denied stealing, She admitted making a mistake, They warned us not to go. Majhul hisobot: It is reported/believed/said that…, The mayor is said to have resigned.', 'Media: broadcast media, print media, online media, headline, journalist, editor, source, bias, coverage, press freedom. Reporting verbs: claim, state, reveal, allege.\nReported speech: He said that he had seen the accident. Reporting verbs: He denied stealing, She admitted making a mistake, They warned us not to go. Passive reporting: It is reported/believed/said that…, The mayor is said to have resigned.'],
      eg: [['The mayor is said to have resigned.', 'Shahar hokimi iste’foga chiqqani aytiladi.'], ['He denied stealing the money.', 'U pulni o‘g‘irlaganini rad etdi.'], ['They warned us not to go there.', 'Ular bizni u yerga bormaslikka ogohlantirdi.'], ['The newspaper revealed the truth.', 'Gazeta haqiqatni ochib berdi.']],
      w: [['headline', 'sarlavha', 'заголовок', 'noun', 'The headline caught my eye.', 'Sarlavha e’tiborimni tortdi.', 'ˈhedlaɪn'], ['coverage', 'yoritish', 'освещение', 'noun', 'The coverage of the event was wide.', 'Voqeani yoritish keng edi.', 'ˈkʌvərɪdʒ'], ['journalist', 'jurnalist', 'журналист', 'noun', 'The journalist interviewed the mayor.', 'Jurnalist hokim bilan suhbatlashdi.', 'ˈdʒɜːnəlɪst'], ['allege', 'da’vo qilmoq (isbotsiz)', 'утверждать', 'verb', 'They allege that he lied.', 'Ular uning yolg‘on gapirganini da’vo qiladi.', 'əˈledʒ'], ['source', 'manba', 'источник', 'noun', 'Always check the source.', 'Manbani doim tekshiring.', 'sɔːs'], ['broadcast', 'efirga uzatmoq', 'транслировать', 'verb', 'The match was broadcast live.', 'O‘yin jonli efirga uzatildi.', 'ˈbrɔːdkɑːst']],
      g: [['The mayor ___ to have resigned.', 'is said', 'says', 'is saying', 'Majhul xabar.'], ['He denied ___ the money.', 'stealing', 'to steal', 'steal', 'deny + -ing.']],
      dlg: ['Editor: Where did you get this information? Journalist: From a reliable source in the council. Editor: The headline says the mayor is believed to have resigned. Journalist: He admitted making a mistake, but he denied leaving. Editor: Then change the headline before we broadcast.', 'What did the mayor deny?', 'Leaving his post', 'Making a mistake', 'Giving an interview', 'He denied leaving.'],
      rd: ['The way news is delivered has changed dramatically. Traditional newspapers and television once dominated, but today most people read headlines on their phones, often through social media. This makes news faster, but it also increases the risk of errors and bias. Journalists are advised to verify every source before publication, and readers should compare coverage from several outlets. Press freedom, experts argue, is essential because it allows the media to hold governments accountable.', ['Why is press freedom essential?', 'It allows the media to hold governments accountable', 'It increases profits', 'It makes news slower'], ['Social media has made news slower.', 'False'], ['Most people trust television most.', 'Not Given']],
      wr: ['Write a news report (10 sentences) about an imaginary event; use reporting verbs and passive reporting.', 'is said|admitted|denied|according to', 70, 'The mayor is said to have resigned yesterday. According to a source in the council, he admitted making a serious mistake. However, he denied taking any money. The council is reported to be preparing a statement. Citizens are warned not to believe rumours.'],
      sp: ['Report in the news style something that happened in your town.', 'A fire is reported to have started in the market. Nobody is said to have been hurt.'],
      ts: [['The title of a news article:', 'headline', 'source', 'coverage'], ['“Manba” in English:', 'source', 'editor', 'motion'], ['She admitted ___ a mistake.', 'making', 'to make', 'make']] },
    { t: ['Advertising techniques', 'Reklama usullari'],
      obj: ['Reklama texnikalarini aniqlab, ularning ta’sirini baholaysiz.', 'You will identify advertising techniques and evaluate their effect.'],
      ex: ['Reklama: slogan, target audience (maqsadli auditoriya), brand loyalty, celebrity endorsement (mashhur tavsiyasi), emotional appeal, bandwagon (“hamma foydalanadi”), limited offer, persuasive. Texnikalar: repetition, rhetorical questions, statistics, testimonials.\nQo‘shma ibora: so … that / such … that (natija): The ad was so catchy that everyone remembered it. Cause–effect: result in, lead to, bring about. Fikr: It could be argued that advertising manipulates; critics point out that…',  'Advertising: slogan, target audience, brand loyalty, celebrity endorsement, emotional appeal, bandwagon, limited offer, persuasive. Techniques: repetition, rhetorical questions, statistics, testimonials.\nResult clauses: so … that / such … that: The ad was so catchy that everyone remembered it. Cause–effect: result in, lead to, bring about. Opinion: It could be argued that advertising manipulates; critics point out that…'],
      eg: [['The ad was so catchy that everyone remembered it.', 'Reklama shunchalik esda qolarli ediki, hamma eslab qoldi.'], ['Celebrity endorsement builds brand loyalty.', 'Mashhurlar tavsiyasi brendga sadoqatni oshiradi.'], ['It was such a persuasive slogan that sales doubled.', 'Bu shunchalik ishonarli shior ediki, savdo ikki baravar oshdi.'], ['Critics point out that advertising can manipulate emotions.', 'Tanqidchilar reklama his-tuyg‘ularni manipulyatsiya qilishi mumkinligini ta’kidlaydi.']],
      w: [['slogan', 'shior', 'слоган', 'noun', 'The slogan is easy to remember.', 'Shior eslab qolish oson.', 'ˈsləʊɡən'], ['endorsement', 'tavsiya (mashhurdan)', 'рекомендация', 'noun', 'Celebrity endorsement sells products.', 'Mashhur tavsiyasi mahsulotni sotadi.', 'ɪnˈdɔːsmənt'], ['persuasive', 'ishontiruvchi', 'убедительный', 'adjective', 'The ad is very persuasive.', 'Reklama juda ishontiruvchi.', 'pəˈsweɪsɪv'], ['target audience', 'maqsadli auditoriya', 'целевая аудитория', 'noun', 'Our target audience is teenagers.', 'Maqsadli auditoriyamiz — o‘smirlar.', 'ˈtɑːɡɪt ˈɔːdiəns'], ['manipulate', 'manipulyatsiya qilmoq', 'манипулировать', 'verb', 'Some ads manipulate emotions.', 'Ba’zi reklamalar his-tuyg‘ularni manipulyatsiya qiladi.', 'məˈnɪpjuleɪt'], ['catchy', 'esda qoladigan', 'запоминающийся', 'adjective', 'A catchy song sells well.', 'Esda qoladigan qo‘shiq yaxshi sotiladi.', 'ˈkætʃi']],
      g: [['The ad was ___ catchy that everyone remembered it.', 'so', 'such', 'too', 'so + sifat + that.'], ['It was ___ a persuasive slogan that sales doubled.', 'such', 'so', 'very', 'such a + sifat + ot + that.']],
      dlg: ['Marketing student: Who is your target audience? Lecturer: Teenagers. Our slogan is so catchy that they repeat it. Student: Do you use celebrity endorsement? Lecturer: Yes, it builds brand loyalty. Student: Critics point out that this can manipulate emotions. Lecturer: That is a fair point.', 'What builds brand loyalty?', 'Celebrity endorsement', 'Low prices', 'Long ads', 'The lecturer says celebrity endorsement.'],
      rd: ['Every day we see hundreds of advertisements, and many are designed to influence our decisions without our noticing. Advertisers use techniques such as emotional appeal, which links a product with happiness, and the bandwagon effect, which suggests that everyone is buying it. Repetition makes slogans memorable, while statistics and testimonials create the impression of reliability. Consumer groups argue that children, who cannot always distinguish advertising from entertainment, need special protection.', ['Who needs special protection?', 'Children', 'Teachers', 'Celebrities'], ['Advertisers avoid using emotions.', 'False'], ['Advertising spending has doubled since 2000.', 'Not Given']],
      wr: ['Analyse an advertisement you know (10 sentences): target audience, techniques and your opinion; use so/such … that.', 'target audience|so|such|persuasive', 70, 'The advertisement I analyse is for a soft drink. Its target audience is teenagers. The slogan is so catchy that people repeat it. It uses celebrity endorsement, which builds brand loyalty. It is such a persuasive advertisement that sales increased. However, critics point out that it manipulates emotions.'],
      sp: ['Describe an advertisement that you remember and why it was effective.', 'The advert was so funny that I remembered the product. Its slogan was very catchy.'],
      ts: [['A short memorable phrase in ads:', 'slogan', 'coverage', 'rebuttal'], ['“Ishontiruvchi” in English:', 'persuasive', 'catchy', 'compelling'], ['It was ___ a good ad that I bought it.', 'such', 'so', 'too']] },
    { t: ['Fake news', 'Soxta yangiliklar'],
      obj: ['Soxta yangiliklarni aniqlash va tarqalishining oldini olish yo‘llarini tushuntirasiz.', 'You will explain how to identify fake news and prevent its spread.'],
      ex: ['Soxta xabarlar: misinformation (bila turib emas), disinformation (qasddan), clickbait, hoax (aldamchi xabar), fact-checking, viral, verify (tekshirmoq), credible source. Belgilar: sensational headline, no author, no sources. Ehtimollik: may/might well, is likely to, is bound to, cannot possibly.\nBuyruq va maslahat: Always check…, Before sharing, ask yourself… Sifat tartibi va qo‘shma sifat: a well-known website, a fact-checking organisation. Passive: Fake stories are often shared without being read.',  'Fake news: misinformation, disinformation, clickbait, hoax, fact-checking, viral, verify, credible source. Signs: sensational headline, no author, no sources. Probability: may/might well, is likely to, is bound to, cannot possibly.\nAdvice: Always check…, Before sharing, ask yourself… Compound adjectives: a well-known website, a fact-checking organisation. Passive: Fake stories are often shared without being read.'],
      eg: [['Fake stories are often shared without being read.', 'Soxta hikoyalar ko‘pincha o‘qilmasdan ulashiladi.'], ['Before sharing, ask yourself who wrote it.', 'Ulashishdan oldin kim yozganini o‘zingizdan so‘rang.'], ['Clickbait headlines are bound to attract attention.', 'Clickbait sarlavhalar e’tiborni tortishi muqarrar.'], ['Fact-checking organisations verify viral claims.', 'Faktlarni tekshiruvchi tashkilotlar viral da’volarni tekshiradi.']],
      w: [['misinformation', 'noto‘g‘ri axborot', 'дезинформация (ошибочная)', 'noun', 'Misinformation spreads quickly.', 'Noto‘g‘ri axborot tez tarqaladi.', 'ˌmɪsɪnfəˈmeɪʃn'], ['disinformation', 'qasddan yolg‘on axborot', 'ложная информация', 'noun', 'Disinformation is spread deliberately.', 'Qasddan yolg‘on axborot ataylab tarqatiladi.', 'ˌdɪsɪnfəˈmeɪʃn'], ['hoax', 'aldamchi xabar', 'мистификация', 'noun', 'The story was a hoax.', 'Hikoya aldamchi xabar edi.', 'həʊks'], ['verify', 'tekshirib tasdiqlamoq', 'проверять', 'verb', 'Verify the claim first.', 'Avval da’voni tekshiring.', 'ˈverɪfaɪ'], ['credible', 'ishonchli (manba)', 'заслуживающий доверия', 'adjective', 'Use credible sources.', 'Ishonchli manbalardan foydalaning.', 'ˈkredəbl'], ['viral', 'tez tarqalgan', 'вирусный', 'adjective', 'The video went viral.', 'Video tez tarqaldi.', 'ˈvaɪrəl']],
      g: [['Fake stories are often shared without ___ read.', 'being', 'be', 'been', 'without + being + V3.'], ['Clickbait headlines are ___ to attract attention.', 'bound', 'must', 'could to', '“be bound to” — muqarrar.']],
      dlg: ['Teacher: How can we recognise fake news? Student: Check whether there is an author and credible sources. Teacher: What else? Student: Sensational headlines are usually a warning sign. Teacher: Before sharing, verify the claim with a fact-checking site. Student: Misinformation spreads fast when nobody checks.', 'What should you do before sharing?', 'Verify the claim', 'Delete it', 'Add a comment', 'The teacher says “verify the claim”.'],
      rd: ['False information is not new, but social media has made it spread faster than ever. Researchers found that false stories are far more likely to be shared than true ones, probably because they provoke strong emotions. Experts distinguish between misinformation, which is shared by people who believe it, and disinformation, which is created deliberately to mislead. To protect themselves, readers should check the source, look for the author’s name, compare coverage and use fact-checking services before sharing a story.', ['Why are false stories shared more often?', 'They provoke strong emotions', 'They are longer', 'They are cheaper'], ['Disinformation is shared by accident.', 'False'], ['Social media was invented in 2000.', 'Not Given']],
      wr: ['Write a guide (10–12 sentences) “How to spot fake news”; use imperatives, passive forms and linking words.', 'check|verify|before|credible', 70, 'To spot fake news, always check the source. Look for the author’s name and credible sources. Sensational headlines are bound to attract attention, but they are often misleading. Before sharing a story, verify it on a fact-checking website. Misinformation is often spread without being checked.'],
      sp: ['Give three tips for recognising fake news.', 'Check the source, look for the author and verify the claim before sharing.'],
      ts: [['A false story spread on purpose:', 'disinformation', 'coverage', 'slogan'], ['“Tekshirmoq” in English:', 'verify', 'broadcast', 'manipulate'], ['The video went ___.', 'viral', 'virus', 'virally']] },
    { t: ['Analysing the media', 'OAVni tahlil qilish'],
      obj: ['Media matnini tanqidiy tahlil qilib, muallif pozitsiyasini aniqlaysiz.', 'You will critically analyse a media text and identify the author’s position.'],
      ex: ['Tahlil: tone (ohang), bias, loaded language (hissiy so‘zlar), omission (qoldirib ketish), framing, headline vs content, target readers. Tanqidiy savollar: Who wrote it? Why? What is left out? Whose voice is missing? Tahlil iboralari: The author implies that…, The tone is critical / ironic, The writer uses emotive language to…\nBir fikr–ikki shakl: Concerning / As regards / With regard to… Kuchaytirish: hardly, scarcely, rarely (inversiya): Rarely do newspapers show both sides.', 'Analysis: tone, bias, loaded language, omission, framing, headline vs content, target readers. Critical questions: Who wrote it? Why? What is left out? Whose voice is missing? Phrases: The author implies that…, The tone is critical / ironic, The writer uses emotive language to…\nWith regard to…, As regards… Inversion with negatives: Rarely do newspapers show both sides.'],
      eg: [['The author implies that the government is hiding something.', 'Muallif hukumat nimanidir yashirayotganini nazarda tutadi.'], ['The writer uses emotive language to shock readers.', 'Yozuvchi o‘quvchilarni larzaga solish uchun hissiy so‘zlardan foydalanadi.'], ['Rarely do newspapers show both sides.', 'Gazetalar kamdan-kam ikkala tomonni ko‘rsatadi.'], ['With regard to the headline, it is misleading.', 'Sarlavhaga kelsak, u chalg‘ituvchi.']],
      w: [['tone', 'ohang', 'тон', 'noun', 'The tone of the article is ironic.', 'Maqolaning ohangi kinoyali.', 'təʊn'], ['imply', 'nazarda tutmoq', 'подразумевать', 'verb', 'The headline implies guilt.', 'Sarlavha aybni nazarda tutadi.', 'ɪmˈplaɪ'], ['emotive', 'hissiy', 'эмоциональный', 'adjective', 'Emotive words influence readers.', 'Hissiy so‘zlar o‘quvchiga ta’sir qiladi.', 'ɪˈməʊtɪv'], ['omission', 'qoldirib ketish', 'пропуск', 'noun', 'Omission can mislead readers.', 'Qoldirib ketish o‘quvchini adashtirishi mumkin.', 'əˈmɪʃn'], ['framing', 'ma’lumotni shakllantirish', 'фрейминг', 'noun', 'Framing affects how we see events.', 'Ma’lumotni shakllantirish voqealarni ko‘rishimizga ta’sir qiladi.', 'ˈfreɪmɪŋ'], ['impartial', 'xolis', 'беспристрастный', 'adjective', 'A good journalist is impartial.', 'Yaxshi jurnalist xolis.', 'ɪmˈpɑːʃl']],
      g: [['Rarely ___ newspapers show both sides.', 'do', 'are', 'have', 'Inversiya: Rarely + do.'], ['The author ___ that the government is hiding something.', 'implies', 'imply', 'implying', 'Birlik.']],
      dlg: ['Lecturer: What is the tone of this article? Student: Critical. The writer uses emotive language to shock readers. Lecturer: What is missing? Student: The government’s point of view. Lecturer: So the omission creates a one-sided picture. Student: Rarely do headlines present both sides.', 'What is missing from the article?', 'The government’s point of view', 'The date', 'The author', 'The student says “the government’s point of view”.'],
      rd: ['When two newspapers report the same event, their stories can look very different. One may describe a protest as “a peaceful gathering”, while another calls it “a violent mob”. Such choices of words, known as framing, shape the way readers understand events. Media analysts therefore ask critical questions: who owns the outlet, what is left out and which sources are quoted? By comparing several versions, readers can form a more balanced picture than any single article could provide.', ['What can readers do to get a balanced picture?', 'Compare several versions', 'Read only one newspaper', 'Ignore the news'], ['All newspapers describe events identically.', 'False'], ['Media analysts are paid by the government.', 'Not Given']],
      wr: ['Analyse two headlines about the same event (invented) and explain tone, framing and bias in 10 sentences.', 'the author implies|tone|framing|rarely', 80, 'The first headline is “Peaceful protest in the centre”, whereas the second says “Violent mob blocks the streets”. The tone of the first is neutral, while the second uses emotive language. The author implies that the protesters are dangerous. This is an example of framing. Rarely do headlines present both sides.'],
      sp: ['Explain what “bias” means in the media with one example.', 'Bias means presenting one side only, for example by using emotive words.'],
      ts: [['Choosing words to shape opinion:', 'framing', 'omission', 'tone'], ['“Xolis” in English:', 'impartial', 'emotive', 'viral'], ['Hardly ___ the news mention the other side.', 'does', 'is', 'has']] },
  ], exam: [['The mayor ___ to have resigned.', 'is said', 'says', 'said to', 'grammar'], ['The advert was ___ funny that I remembered it.', 'so', 'such', 'too', 'grammar'], ['A short phrase that sells a product:', 'slogan', 'headline', 'source', 'vocabulary']] },

  { title: 'Environment and energy', lessons: [
    { t: ['Energy sources', 'Energiya manbalari'],
      obj: ['Energiya manbalarini taqqoslab, afzallik va kamchiliklarni baholaysiz.', 'You will compare energy sources and evaluate pros and cons.'],
      ex: ['Manbalar: coal, oil, natural gas, nuclear power, hydroelectric, solar, wind, geothermal, biomass. Atamalar: finite (cheklangan) vs renewable, emissions, capacity, grid (tarmoq), reliable, intermittent (uzilib-uzilib). Taqqoslash: far cleaner than, nowhere near as reliable as, the cheapest of all. \nMajhul: Coal is burned to generate electricity. Nuclear energy is considered to be… Natijaviy: Consequently, as a result, which leads to… Nisbiy gap: Solar power, which has become cheaper, is spreading fast.',  'Sources: coal, oil, natural gas, nuclear power, hydroelectric, solar, wind, geothermal, biomass. Terms: finite vs renewable, emissions, capacity, grid, reliable, intermittent. Comparison: far cleaner than, nowhere near as reliable as, the cheapest of all.\nPassive: Coal is burned to generate electricity. Nuclear energy is considered to be… Result: Consequently, as a result, which leads to… Relative clause: Solar power, which has become cheaper, is spreading fast.'],
      eg: [['Solar power is far cleaner than coal.', 'Quyosh energiyasi ko‘mirdan ancha toza.'], ['Wind power is nowhere near as reliable as gas.', 'Shamol energiyasi gazdek ishonchli emas.'], ['Coal is burned to generate electricity.', 'Ko‘mir elektr ishlab chiqarish uchun yoqiladi.'], ['Solar power, which has become cheaper, is spreading fast.', 'Arzonlashgan quyosh energiyasi tez tarqalmoqda.']],
      w: [['finite', 'cheklangan', 'ограниченный', 'adjective', 'Oil is a finite resource.', 'Neft cheklangan resurs.', 'ˈfaɪnaɪt'], ['emissions', 'chiqindi gazlar', 'выбросы', 'noun', 'Emissions must fall.', 'Chiqindi gazlar kamayishi kerak.', 'ɪˈmɪʃnz'], ['hydroelectric', 'gidroelektr', 'гидроэлектрический', 'adjective', 'A hydroelectric dam produces power.', 'Gidroelektr to‘g‘on quvvat ishlab chiqaradi.', 'ˌhaɪdrəʊɪˈlektrɪk'], ['intermittent', 'uzilib turuvchi', 'прерывистый', 'adjective', 'Solar power is intermittent.', 'Quyosh energiyasi uzilib turadi.', 'ˌɪntəˈmɪtənt'], ['grid', 'energiya tarmog‘i', 'сеть', 'noun', 'The grid supplies homes.', 'Tarmoq uylarni ta’minlaydi.', 'ɡrɪd'], ['generate', 'ishlab chiqarmoq', 'вырабатывать', 'verb', 'Turbines generate electricity.', 'Turbinalar elektr ishlab chiqaradi.', 'ˈdʒenəreɪt']],
      g: [['Solar power is ___ cleaner than coal.', 'far', 'very', 'so', 'far + qiyosiy.'], ['Coal ___ to generate electricity.', 'is burned', 'burns', 'is burning', 'Majhul.']],
      dlg: ['Engineer: Coal is cheap, but it is finite and produces emissions. Student: What about solar power? Engineer: It is far cleaner, though it is intermittent. Student: Could wind and hydroelectric power make up the difference? Engineer: Combined with a modern grid, they could generate most of our electricity.', 'What is the disadvantage of solar power?', 'It is intermittent', 'It is finite', 'It is too dirty', 'The engineer says it is intermittent.'],
      rd: ['The world’s energy mix is slowly changing. Fossil fuels still supply about 80 per cent of energy, but their emissions are the main cause of climate change. Solar and wind power, whose cost has fallen sharply, now generate a growing share of electricity. Their main weakness is intermittency: the sun does not always shine and the wind does not always blow. Therefore, experts stress the importance of storage technologies and flexible grids, and some countries continue to rely on nuclear power as a low-carbon baseload.', ['What is the main weakness of solar and wind?', 'Intermittency', 'High emissions', 'Low cost'], ['Fossil fuels supply a small share of energy.', 'False'], ['Nuclear power is banned in Europe.', 'Not Given']],
      wr: ['Compare two energy sources (10–12 sentences) using comparison structures and a relative clause.', 'far|nowhere near|which|as a result', 80, 'Coal and solar power are two very different energy sources. Solar power is far cleaner than coal, which produces large emissions. However, solar energy is nowhere near as reliable as coal because it is intermittent. As a result, many countries use a mix of sources. Storage technology could solve the problem.'],
      sp: ['Say which energy source you think is best for your country and why.', 'I think solar power is best because it is clean and my country has a lot of sunshine.'],
      ts: [['Not unlimited:', 'finite', 'intermittent', 'reliable'], ['“Ishlab chiqarmoq” (energiya):', 'generate', 'emit', 'burn'], ['Wind power is ___ as reliable as gas.', 'not as', 'much', 'so']] },
    { t: ['Sustainability', 'Barqarorlik'],
      obj: ['Barqaror rivojlanish tushunchasini tushuntirib, amaliy misollar keltirasiz.', 'You will explain sustainable development and give practical examples.'],
      ex: ['Barqarorlik: sustainable development, carbon footprint (uglerod izi), eco-friendly, biodegradable, circular economy, conservation (muhofaza), renewable resources, greenwashing. Ta’rif: Sustainability means meeting present needs without compromising future generations.\nMaqsad va yo‘l: aim to + fe’l, with a view to + -ing, in an effort to. Majburiyat: It is high time (vaqt keldi) + Past Simple: It is high time we reduced waste. Shartli: Provided that, so long as. Qiyos: the more …, the less …',  'Sustainability: sustainable development, carbon footprint, eco-friendly, biodegradable, circular economy, conservation, renewable resources, greenwashing. Definition: Sustainability means meeting present needs without compromising future generations.\nPurpose: aim to + verb, with a view to + -ing, in an effort to. Urgency: It is high time + Past Simple: It is high time we reduced waste. Condition: Provided that, so long as. Comparison: the more …, the less …'],
      eg: [['It is high time we reduced waste.', 'Chiqindini kamaytirish vaqti keldi.'], ['Biodegradable packaging breaks down naturally.', 'Biologik parchalanuvchi qadoq tabiiy ravishda parchalanadi.'], ['Many companies aim to cut their carbon footprint.', 'Ko‘p kompaniyalar uglerod izini kamaytirishni maqsad qiladi.'], ['Greenwashing misleads consumers.', 'Greenwashing iste’molchilarni chalg‘itadi.']],
      w: [['sustainable', 'barqaror', 'устойчивый', 'adjective', 'We need sustainable solutions.', 'Bizga barqaror yechimlar kerak.', 'səˈsteɪnəbl'], ['carbon footprint', 'uglerod izi', 'углеродный след', 'noun', 'Flying increases your carbon footprint.', 'Uchish uglerod izingizni oshiradi.', 'ˈkɑːbən ˈfʊtprɪnt'], ['biodegradable', 'biologik parchalanuvchi', 'биоразлагаемый', 'adjective', 'Biodegradable bags are better.', 'Biologik parchalanuvchi paketlar yaxshiroq.', 'ˌbaɪəʊdɪˈɡreɪdəbl'], ['conservation', 'muhofaza', 'охрана', 'noun', 'Conservation protects wildlife.', 'Muhofaza yovvoyi tabiatni asraydi.', 'ˌkɒnsəˈveɪʃn'], ['greenwashing', 'yashil niqoblash', 'гринвошинг', 'noun', 'Greenwashing is common in advertising.', 'Yashil niqoblash reklamada keng tarqalgan.', 'ˈɡriːnwɒʃɪŋ'], ['eco-friendly', 'ekologik toza', 'экологичный', 'adjective', 'Choose eco-friendly products.', 'Ekologik toza mahsulotlarni tanlang.', 'ˈiːkəʊ ˈfrendli']],
      g: [['It is high time we ___ waste.', 'reduced', 'reduce', 'will reduce', '“It is high time” + Past Simple.'], ['The more we recycle, ___ waste there is.', 'the less', 'less', 'the least', 'Ikkilangan qiyos.']],
      dlg: ['Presenter: What does sustainability mean? Activist: Meeting our needs without compromising future generations. Presenter: What can individuals do? Activist: Reduce their carbon footprint and choose eco-friendly products. Presenter: Beware of greenwashing, though. Activist: Yes, it is high time companies were honest.', 'What should consumers beware of?', 'Greenwashing', 'Recycling', 'Biodegradable bags', 'The presenter says “Beware of greenwashing”.'],
      rd: ['The concept of sustainable development was popularised in 1987 as development that meets the needs of the present without compromising the ability of future generations to meet their own. In practice, this means using resources at a rate at which they can be renewed, reducing pollution and protecting biodiversity. Businesses increasingly advertise sustainable credentials, but critics warn of greenwashing, in which products are described as eco-friendly without real evidence. Consumers are therefore advised to look for independent certification.', ['What should consumers look for?', 'Independent certification', 'Bigger packaging', 'Lower prices only'], ['Sustainability harms future generations.', 'False'], ['The 1987 report was written in Sweden.', 'Not Given']],
      wr: ['Write an essay paragraph (10–12 sentences) on what individuals and companies can do to live more sustainably.', 'it is high time|the more|carbon footprint|aim to', 80, 'It is high time we changed our habits. Individuals can reduce their carbon footprint by using public transport. Companies should aim to use biodegradable packaging. The more we recycle, the less waste there is. Consumers should also beware of greenwashing.'],
      sp: ['Say three things you do to live sustainably.', 'I use public transport, I recycle and I buy eco-friendly products.'],
      ts: [['Misleading green claims:', 'greenwashing', 'conservation', 'emissions'], ['“Muhofaza” in English:', 'conservation', 'generation', 'footprint'], ['It is high time we ___ more trees.', 'planted', 'plant', 'will plant']] },
    { t: ['Environmental policy', 'Ekologik siyosat'],
      obj: ['Ekologik siyosat choralarini (soliq, qonun, subsidiya) baholaysiz.', 'You will evaluate environmental policy measures (taxes, laws, subsidies).'],
      ex: ['Siyosat: regulation, legislation, subsidy (subsidiya), carbon tax, emissions trading, ban, penalty / fine, incentive (rag‘bat), enforce (amalga oshirmoq), international agreement. Fikr: In my view, the most effective measure would be…, Critics argue that…, Supporters point out that…\nZaruriyat va majbur: be obliged to, be required to, be forced to. Majhul hisobot: It is estimated that…, It has been argued that… Shartli aralash: If governments had acted earlier, we would not be facing this crisis today.',  'Policy: regulation, legislation, subsidy, carbon tax, emissions trading, ban, penalty / fine, incentive, enforce, international agreement. Opinion: In my view, the most effective measure would be…, Critics argue that…, Supporters point out that…\nObligation: be obliged to, be required to, be forced to. Passive reporting: It is estimated that…, It has been argued that… Mixed conditional: If governments had acted earlier, we would not be facing this crisis today.'],
      eg: [['If governments had acted earlier, we would not be facing this crisis today.', 'Hukumatlar erta harakat qilganida, bugun bu inqirozga duch kelmas edik.'], ['Factories are required to reduce emissions.', 'Zavodlar chiqindilarni kamaytirishga majbur.'], ['Subsidies encourage people to buy electric cars.', 'Subsidiyalar odamlarni elektr avtomobil olishga rag‘batlantiradi.'], ['It is estimated that plastic waste doubled in ten years.', 'Plastik chiqindi o‘n yilda ikki baravar oshgani taxmin qilinadi.']],
      w: [['subsidy', 'subsidiya', 'субсидия', 'noun', 'The subsidy lowers prices.', 'Subsidiya narxlarni pasaytiradi.', 'ˈsʌbsədi'], ['legislation', 'qonunchilik', 'законодательство', 'noun', 'New legislation was introduced.', 'Yangi qonunchilik joriy etildi.', 'ˌledʒɪsˈleɪʃn'], ['incentive', 'rag‘bat', 'стимул', 'noun', 'Tax breaks are an incentive.', 'Soliq imtiyozlari rag‘bat bo‘ladi.', 'ɪnˈsentɪv'], ['enforce', 'amalga oshirmoq (qonunni)', 'обеспечивать соблюдение', 'verb', 'Police enforce the law.', 'Politsiya qonunni amalga oshiradi.', 'ɪnˈfɔːs'], ['penalty', 'jarima, jazo', 'штраф', 'noun', 'The penalty is a heavy fine.', 'Jazo — og‘ir jarima.', 'ˈpenəlti'], ['agreement', 'kelishuv', 'соглашение', 'noun', 'An international agreement was signed.', 'Xalqaro kelishuv imzolandi.', 'əˈɡriːmənt']],
      g: [['If governments ___ earlier, we would not be facing this crisis.', 'had acted', 'acted', 'act', 'Aralash shartli.'], ['Factories ___ to reduce emissions.', 'are required', 'requires', 'require to', 'Majhul.']],
      dlg: ['Reporter: What is the most effective environmental policy? Minister: In my view, a carbon tax combined with subsidies for clean energy. Reporter: Critics argue that taxes hurt families. Minister: Supporters point out that the revenue can be returned as incentives. Reporter: If we had acted earlier, would the problem be smaller? Minister: Undoubtedly.', 'What does the minister prefer?', 'A carbon tax with subsidies for clean energy', 'A complete ban on cars', 'No policy', 'He says “a carbon tax combined with subsidies”.'],
      rd: ['Governments use a variety of tools to protect the environment. Regulations set limits on pollution and are enforced through fines. Economic instruments, such as carbon taxes and emissions trading, make polluting more expensive, while subsidies make clean technologies more affordable. International agreements, for example the Paris Agreement, commit countries to cut emissions together. Economists generally agree that combining incentives with clear legislation is more effective than relying on either alone.', ['What is generally considered most effective?', 'Combining incentives with legislation', 'Relying on fines only', 'Doing nothing'], ['Subsidies make clean technology more expensive.', 'False'], ['The Paris Agreement was signed in Asia.', 'Not Given']],
      wr: ['Write a short policy proposal (10–12 sentences) to reduce air pollution in a city; justify the measures.', 'in my view|would|supporters point out|incentive', 80, 'In my view, the most effective measure to reduce air pollution would be to ban old cars from the centre. Subsidies for electric vehicles would also work as an incentive. Supporters point out that cleaner air reduces health costs. Critics argue that it is expensive. However, if we had acted earlier, the problem would be smaller today.'],
      sp: ['Say which policy would reduce pollution most in your city and why.', 'In my view, a ban on old cars would work best. It would clean the air quickly.'],
      ts: [['Money given by the state to lower prices:', 'subsidy', 'penalty', 'incentive'], ['“Qonunchilik” in English:', 'legislation', 'enforcement', 'agreement'], ['If we ___ earlier, it would be better now.', 'had started', 'started', 'start']] },
    { t: ['An environment essay', 'Atrof-muhit haqida esse'],
      obj: ['Atrof-muhit mavzusida murakkab argumentativ esse yozasiz.', 'You will write a complex argumentative essay on an environmental topic.'],
      ex: ['Esse bo‘yicha reja: 1) Paragraph hook (jalb qiluvchi gap) + background + thesis; 2) Argument 1 + evidence; 3) Argument 2 + counter-argument; 4) Conclusion — kelajak yoki tavsiya. Murakkab gap: Although…, the evidence suggests that…, Whilst it is true that…, it must be acknowledged that… Aniq va ehtiyotkor ifoda: This would seem to indicate…, It is arguable that…\nKo‘rsatkichlar: a growing body of evidence, the overwhelming majority of scientists. Lexik aniqlik: Replace “big problem” with “pressing issue”, “bad” with “detrimental”.',  'Essay plan: 1) Hook + background + thesis; 2) Argument 1 + evidence; 3) Argument 2 + counter-argument; 4) Conclusion — future or recommendation. Complex sentences: Although…, the evidence suggests that…, Whilst it is true that…, it must be acknowledged that… Cautious language: This would seem to indicate…, It is arguable that…\nEvidence: a growing body of evidence, the overwhelming majority of scientists. Precise lexis: “pressing issue” instead of “big problem”, “detrimental” instead of “bad”.'],
      eg: [['A growing body of evidence suggests that the climate is changing.', 'Tobora ko‘payib borayotgan dalillar iqlim o‘zgarayotganini ko‘rsatadi.'], ['Whilst it is true that costs are high, the benefits are greater.', 'Xarajatlar yuqori bo‘lsa-da, foydalar kattaroq.'], ['It must be acknowledged that change takes time.', 'O‘zgarish vaqt olishini tan olish kerak.'], ['Plastic pollution is a pressing issue.', 'Plastik ifloslanish dolzarb masala.']],
      w: [['pressing', 'dolzarb', 'неотложный', 'adjective', 'It is a pressing issue.', 'Bu dolzarb masala.', 'ˈpresɪŋ'], ['detrimental', 'zararli', 'вредный', 'adjective', 'Smoking is detrimental to health.', 'Chekish sog‘liq uchun zararli.', 'ˌdetrɪˈmentl'], ['acknowledge', 'tan olmoq', 'признавать', 'verb', 'We must acknowledge the risks.', 'Biz xavflarni tan olishimiz kerak.', 'əkˈnɒlɪdʒ'], ['overwhelming', 'ulkan, ezib tashlovchi', 'подавляющий', 'adjective', 'The majority is overwhelming.', 'Ko‘pchilik ezib tashlovchi.', 'ˌəʊvəˈwelmɪŋ'], ['arguable', 'bahsli, ishonarli', 'спорный', 'adjective', 'It is arguable that this is true.', 'Bu to‘g‘ri deyish mumkin.', 'ˈɑːɡjuəbl'], ['body of evidence', 'dalillar to‘plami', 'совокупность доказательств', 'noun', 'A body of evidence supports it.', 'Dalillar to‘plami buni qo‘llab-quvvatlaydi.', 'ˈbɒdi əv ˈevɪdəns']],
      g: [['___ it is true that costs are high, the benefits are greater.', 'Whilst', 'Despite', 'Because', 'Qarama-qarshilik.'], ['It must be ___ that change takes time.', 'acknowledged', 'acknowledge', 'acknowledging', 'Majhul.']],
      dlg: ['Teacher: How do you start a strong essay? Student: With a hook and clear thesis. Teacher: What about the middle? Student: Two arguments, one with a counter-argument. Teacher: And precise language? Student: I replace “big problem” with “pressing issue”. Teacher: Excellent.', 'What does the student replace “big problem” with?', 'Pressing issue', 'Detrimental', 'Overwhelming', 'The student says “pressing issue”.'],
      rd: ['Plastic pollution is arguably one of the most pressing environmental issues of our time. A growing body of evidence shows that microplastics are now present in oceans, soil and even drinking water. Whilst it is true that plastic has made products cheaper and safer, its long-term effects on ecosystems are detrimental. It must be acknowledged that individual action alone is insufficient; governments must introduce stricter regulations. In conclusion, only a combination of legislation and changed habits can solve the problem.', ['What does the writer conclude?', 'Legislation and changed habits are both needed', 'Only individuals must act', 'Plastic is harmless'], ['The writer thinks plastic has made nothing cheaper.', 'False'], ['The essay was published in a newspaper.', 'Not Given']],
      wr: ['Write an argumentative essay (250–280 words): “Individuals, not governments, are responsible for protecting the environment.” Discuss.', 'whilst it is true|it must be acknowledged|a growing body of evidence|in conclusion', 190, 'Environmental protection is a pressing issue, and opinions differ on who is responsible. Whilst it is true that individuals can reduce waste, it must be acknowledged that their influence is limited. A growing body of evidence shows that industry causes most emissions. Therefore, governments must introduce strict regulations. In conclusion, responsibility should be shared.'],
      sp: ['Present a thesis on who should protect the environment and one reason.', 'In my view, responsibility should be shared. Governments make rules, but individuals must follow them.'],
      ts: [['Very urgent:', 'pressing', 'arguable', 'overwhelming'], ['“Tan olmoq” in English:', 'acknowledge', 'enforce', 'imply'], ['Smoking is ___ to health.', 'detrimental', 'detrimentally', 'detriment']] },
  ], exam: [['It is high time we ___ our habits.', 'changed', 'change', 'will change', 'grammar'], ['If governments ___ earlier, the crisis would be smaller.', 'had acted', 'acted', 'would act', 'grammar'], ['Not renewable, will run out:', 'finite', 'biodegradable', 'sustainable', 'vocabulary']] },

  { title: 'History and heritage', lessons: [
    { t: ['Historical events', 'Tarixiy voqealar'],
      obj: ['Tarixiy voqealarni ketma-ketlik va sabab-oqibat bilan bayon qilasiz.', 'You will narrate historical events with sequence and cause–effect.'],
      ex: ['Tarixiy bayon: Past Simple, Past Perfect, majhul: The city was founded in 1220 and destroyed ten years later. Ketma-ketlik: by the time, prior to, subsequently (keyinchalik), eventually, in the aftermath of (… oqibatida). Atamalar: empire, dynasty, revolution, invasion, treaty (shartnoma), reign (hukmronlik), era, conquer (zabt etmoq), uprising.\nPast Perfect: By the time the army arrived, the city had already fallen. Vaqt belgilar: in the 13th century, during the reign of…, between 1500 and 1600.', 'Narration: Past Simple, Past Perfect, passive: The city was founded in 1220 and destroyed ten years later. Sequence: by the time, prior to, subsequently, eventually, in the aftermath of. Terms: empire, dynasty, revolution, invasion, treaty, reign, era, conquer, uprising.\nPast Perfect: By the time the army arrived, the city had already fallen. Time: in the 13th century, during the reign of…, between 1500 and 1600.'],
      eg: [['By the time the army arrived, the city had already fallen.', 'Qo‘shin yetib kelganda, shahar allaqachon qulagan edi.'], ['The empire was founded in the 14th century.', 'Imperiya XIV asrda tashkil etilgan.'], ['In the aftermath of the war, a treaty was signed.', 'Urushdan keyin shartnoma imzolandi.'], ['Subsequently, the dynasty lost power.', 'Keyinchalik sulola hokimiyatni yo‘qotdi.']],
      w: [['empire', 'imperiya', 'империя', 'noun', 'The empire stretched across Asia.', 'Imperiya Osiyo bo‘ylab yoyilgan edi.', 'ˈempaɪə'], ['dynasty', 'sulola', 'династия', 'noun', 'The dynasty ruled for 200 years.', 'Sulola 200 yil hukmronlik qildi.', 'ˈdɪnəsti'], ['treaty', 'shartnoma', 'договор', 'noun', 'A peace treaty ended the war.', 'Tinchlik shartnomasi urushni tugatdi.', 'ˈtriːti'], ['conquer', 'zabt etmoq', 'завоёвывать', 'verb', 'They conquered the region.', 'Ular hududni zabt etdi.', 'ˈkɒŋkə'], ['reign', 'hukmronlik', 'правление', 'noun', 'During his reign, trade flourished.', 'Uning hukmronligi davrida savdo gullab-yashnadi.', 'reɪn'], ['uprising', 'qo‘zg‘olon', 'восстание', 'noun', 'The uprising was suppressed.', 'Qo‘zg‘olon bostirildi.', 'ˈʌpraɪzɪŋ']],
      g: [['By the time the army arrived, the city ___ already fallen.', 'had', 'has', 'was', 'Past Perfect.'], ['The empire ___ in the 14th century.', 'was founded', 'founded', 'is founded', 'Majhul o‘tgan.']],
      dlg: ['Guide: This dynasty ruled during the 14th century. Tourist: How did it begin? Guide: Its founder conquered the region, and subsequently built the capital. By the time he died, the empire had reached its greatest size. Tourist: What happened afterwards? Guide: A series of uprisings weakened it.', 'What weakened the empire?', 'A series of uprisings', 'A treaty', 'A flood', 'The guide says “a series of uprisings”.'],
      rd: ['The Timurid Empire was founded in the late 14th century by Amir Timur, who conquered vast territories from India to the Mediterranean. He made Samarkand his capital and invited architects and scholars to build monuments that still stand today. By the time of his death in 1405, the empire had reached its greatest extent, but disputes among his successors weakened it. Subsequently, his grandson Ulugh Beg, who ruled in the 15th century, became famous as a scientist and astronomer rather than a conqueror.', ['Who was Ulugh Beg?', 'A scientist and astronomer who ruled', 'A foreign invader', 'A merchant'], ['The empire grew after Timur died.', 'False'], ['Timur was born in Samarkand.', 'Not Given']],
      wr: ['Narrate a historical event or period you know (10–12 sentences) using Past Simple, Past Perfect and passive forms.', 'by the time|had|was founded|subsequently', 80, 'The city of Samarkand was founded many centuries ago. By the time of Timur’s reign, it had become an important trade centre. Timur made it his capital. Many monuments were built during his rule. Subsequently, his grandson Ulugh Beg built an observatory. In the aftermath of Timur’s death, the empire gradually weakened.'],
      sp: ['Tell the history of a famous place in your country in a few sentences.', 'The city was founded long ago. By the 14th century it had become a capital. Many monuments were built there.'],
      ts: [['A family of rulers:', 'dynasty', 'treaty', 'reign'], ['“Zabt etmoq” in English:', 'conquer', 'reign', 'found'], ['By the time we arrived, the shop ___ closed.', 'had', 'has', 'was been']] },
    { t: ['Heritage and tourism', 'Meros va turizm'],
      obj: ['Madaniy meros va turizm o‘rtasidagi muvozanatni muhokama qilasiz.', 'You will discuss the balance between cultural heritage and tourism.'],
      ex: ['Meros: heritage site (meros obyekti), UNESCO World Heritage, preservation / restoration (tiklash), authenticity, landmark (diqqatga sazovor joy), overtourism, visitor numbers, revenue from tourism. Fikr: Tourism brings economic benefits, but it can also damage fragile sites.\nGerundiy va infinitiv: allow tourists to enter, prevent sites from being damaged, limit visitors to… Qiyosiy: the more popular a site becomes, the greater the risk of damage. Passive reporting: The site is believed to date back to the 8th century.', 'Heritage: heritage site, UNESCO World Heritage, preservation / restoration, authenticity, landmark, overtourism, visitor numbers, revenue from tourism. Opinion: Tourism brings economic benefits, but it can also damage fragile sites.\nGerund and infinitive: allow tourists to enter, prevent sites from being damaged, limit visitors to… Comparison: the more popular a site becomes, the greater the risk of damage. Passive reporting: The site is believed to date back to the 8th century.'],
      eg: [['The site is believed to date back to the 8th century.', 'Obyekt VIII asrga borib taqalishi taxmin qilinadi.'], ['The more popular a site becomes, the greater the risk of damage.', 'Obyekt qanchalik mashhur bo‘lsa, shikastlanish xavfi shunchalik katta.'], ['Limiting visitor numbers prevents sites from being damaged.', 'Tashrif buyuruvchilar sonini cheklash obyektlarni shikastlanishdan saqlaydi.'], ['Restoration should respect the original design.', 'Tiklash asl dizaynni hurmat qilishi kerak.']],
      w: [['heritage', 'meros', 'наследие', 'noun', 'The city is a World Heritage site.', 'Shahar Jahon merosi obyekti.', 'ˈherɪtɪdʒ'], ['restoration', 'tiklash', 'реставрация', 'noun', 'The restoration took ten years.', 'Tiklash o‘n yil davom etdi.', 'ˌrestəˈreɪʃn'], ['authenticity', 'haqiqiylik', 'подлинность', 'noun', 'Authenticity attracts tourists.', 'Haqiqiylik sayyohlarni jalb qiladi.', 'ˌɔːθenˈtɪsəti'], ['landmark', 'diqqatga sazovor joy', 'достопримечательность', 'noun', 'The tower is a famous landmark.', 'Minora mashhur diqqatga sazovor joy.', 'ˈlændmɑːk'], ['fragile', 'mo‘rt', 'хрупкий', 'adjective', 'The paintings are fragile.', 'Rasmlar mo‘rt.', 'ˈfrædʒaɪl'], ['overtourism', 'haddan ortiq turizm', 'чрезмерный туризм', 'noun', 'Overtourism harms old towns.', 'Haddan ortiq turizm eski shaharlarga zarar yetkazadi.', 'ˌəʊvəˈtʊərɪzəm']],
      g: [['The site ___ to date back to the 8th century.', 'is believed', 'believes', 'is believing', 'Majhul xabar.'], ['The ___ popular a site becomes, the greater the risk.', 'more', 'most', 'much', 'Ikkilangan qiyos.']],
      dlg: ['Councillor: Visitor numbers have doubled. Conservator: The more popular the site becomes, the greater the risk of damage. Councillor: But tourism brings revenue. Conservator: Yes, though limiting numbers would prevent the paintings from being damaged. Councillor: Perhaps we should introduce timed tickets.', 'What does the conservator suggest?', 'Limiting visitor numbers', 'Closing the site', 'Raising prices only', 'He says “limiting numbers”.'],
      rd: ['Heritage tourism is one of the fastest-growing sectors worldwide. Visitors spend money on tickets, hotels and local crafts, which supports communities and pays for restoration. Yet popular sites face serious pressure: crowds, pollution and souvenir trade can threaten authenticity and damage fragile structures. Some places have responded with timed tickets, visitor caps and higher fees for foreigners. Experts agree that sustainable tourism must put preservation first, since a damaged monument cannot be replaced.', ['What must sustainable tourism put first?', 'Preservation', 'Souvenirs', 'Hotels'], ['Heritage tourism is shrinking.', 'False'], ['Visitor caps were introduced in 1990.', 'Not Given']],
      wr: ['Write a for-and-against paragraph (10–12 sentences) on tourism at heritage sites and propose a solution.', 'the more|revenue|prevent|should', 80, 'Tourism at heritage sites has both advantages and drawbacks. It brings revenue that pays for restoration. However, the more popular a site becomes, the greater the risk of damage. Limiting visitor numbers could prevent monuments from being harmed. Timed tickets should be introduced. Authenticity must be protected.'],
      sp: ['Explain whether you think visitor numbers at historic sites should be limited.', 'I think visitor numbers should be limited. It would prevent sites from being damaged.'],
      ts: [['Easy to break or damage:', 'fragile', 'authentic', 'popular'], ['“Tiklash” in English:', 'restoration', 'landmark', 'heritage'], ['Limiting tickets prevents damage ___ happening.', 'from', 'of', 'to']] },
    { t: ['Museums and culture', 'Muzeylar va madaniyat'],
      obj: ['Muzeylar, ko‘rgazmalar va san’at haqida fikr bildirasiz va tavsiya berasiz.', 'You will express opinions and recommendations about museums, exhibitions and art.'],
      ex: ['Muzey: exhibit (eksponat), exhibition, collection, curator (kurator), artefact, gallery, guided tour, admission fee, interactive displays. Tavsif: The exhibition features / showcases / displays… Fikr: I found it thought-provoking / disappointing / overrated. \nRelative clauses (kengaytirilgan): The museum, whose collection includes rare manuscripts, attracts scholars. Participle: Housed in a former palace, the museum is one of the largest. Kuchaytirish: What impressed me most was…, It was the paintings that I enjoyed.', 'Museum: exhibit, exhibition, collection, curator, artefact, gallery, guided tour, admission fee, interactive displays. Description: The exhibition features / showcases / displays… Opinion: I found it thought-provoking / disappointing / overrated.\nRelative clauses: The museum, whose collection includes rare manuscripts, attracts scholars. Participle: Housed in a former palace, the museum is one of the largest. Cleft: What impressed me most was…, It was the paintings that I enjoyed.'],
      eg: [['Housed in a former palace, the museum is one of the largest.', 'Sobiq saroyda joylashgan muzey eng kattalaridan biri.'], ['What impressed me most was the interactive display.', 'Meni eng ko‘p hayratga solgani interaktiv ko‘rgazma bo‘ldi.'], ['The exhibition showcases ancient manuscripts.', 'Ko‘rgazma qadimiy qo‘lyozmalarni namoyish etadi.'], ['It was the paintings that I enjoyed.', 'Menga yoqqani aynan rasmlar edi.']],
      w: [['exhibit', 'eksponat', 'экспонат', 'noun', 'The main exhibit is a golden mask.', 'Asosiy eksponat — oltin niqob.', 'ɪɡˈzɪbɪt'], ['curator', 'kurator', 'куратор', 'noun', 'The curator explained each item.', 'Kurator har bir narsani tushuntirdi.', 'kjʊˈreɪtə'], ['artefact', 'artefakt', 'артефакт', 'noun', 'The artefact is 3,000 years old.', 'Artefakt 3000 yillik.', 'ˈɑːtɪfækt'], ['manuscript', 'qo‘lyozma', 'рукопись', 'noun', 'A rare manuscript was displayed.', 'Noyob qo‘lyozma namoyish etildi.', 'ˈmænjuskrɪpt'], ['thought-provoking', 'o‘ylantiruvchi', 'заставляющий задуматься', 'adjective', 'The film was thought-provoking.', 'Film o‘ylantiruvchi edi.', 'ˈθɔːt prəvəʊkɪŋ'], ['overrated', 'ortiqcha baholangan', 'переоценённый', 'adjective', 'I found the show overrated.', 'Shouni ortiqcha baholangan deb topdim.', 'ˌəʊvəˈreɪtɪd']],
      g: [['___ in a former palace, the museum is large.', 'Housed', 'Housing', 'House', 'Passiv sifatdosh.'], ['What impressed me most ___ the interactive display.', 'was', 'were', 'is being', 'Cleft: What ... was.']],
      dlg: ['Friend: How was the exhibition? Anna: Thought-provoking. What impressed me most was the interactive display. Friend: Was it expensive? Anna: The admission fee was reasonable. Friend: Did you take the guided tour? Anna: Yes, the curator explained each artefact.', 'What impressed Anna most?', 'The interactive display', 'The price', 'The building', 'She says the interactive display.'],
      rd: ['Museums are no longer quiet places where visitors simply look at objects behind glass. Many now offer interactive displays, workshops and virtual tours that help people engage with history. Curators point out that this approach attracts younger audiences, who may find traditional exhibitions boring. Nevertheless, some critics argue that technology can distract from the real artefacts, whose value lies in their authenticity. Most agree that the best museums combine both: they use technology to explain the object, not to replace it.', ['What do the best museums do?', 'Use technology to explain objects, not replace them', 'Remove all objects', 'Avoid young visitors'], ['Museums are quiet places without technology.', 'False'], ['Admission is free in all museums.', 'Not Given']],
      wr: ['Write a review (10–12 sentences) of a museum or exhibition you visited (real or imagined); use cleft sentences and participle clauses.', 'what impressed me|housed in|thought-provoking|i would recommend', 80, 'Housed in a former palace, the museum is one of the largest in the country. What impressed me most was the collection of rare manuscripts. The guided tour was thought-provoking. I found the interactive displays very helpful. I would recommend it to anyone interested in history.'],
      sp: ['Recommend a museum or exhibition you like and say why.', 'Housed in an old palace, the museum has a great collection. I would recommend it.'],
      ts: [['A person who organises exhibitions:', 'curator', 'exhibit', 'artefact'], ['“Qo‘lyozma” in English:', 'manuscript', 'artefact', 'gallery'], ['It was the music ___ I enjoyed.', 'that', 'what', 'where']] },
    { t: ['Writing about the past', 'O‘tmish haqida yozish'],
      obj: ['O‘tmish haqida (tarixiy yoki shaxsiy) tafsilotli matn yozasiz.', 'You will write a detailed text about the past (historical or personal).'],
      ex: ['O‘tmish haqida matn: sarlavha → kirish (kontekst) → voqealar xronologiyasi → ta’sir/ahamiyat → xulosa. Zamonlar: Past Simple (asosiy voqealar), Past Continuous (fon), Past Perfect (undan oldingi), used to / would (odat). Bog‘lovchilar: Initially (dastlab), Meanwhile, Following this, As a result, Ultimately (oxir-oqibat), In retrospect (ortga nazar).\nHikoyaviy uslub: tasviriy fe’llar (emerge, flourish, decline, collapse), ot ifodalar: the rise and fall of…, the outbreak of…',  'Text about the past: title → introduction (context) → chronology of events → impact/significance → conclusion. Tenses: Past Simple (main events), Past Continuous (background), Past Perfect (earlier), used to / would (habits). Linkers: Initially, Meanwhile, Following this, As a result, Ultimately, In retrospect.\nNarrative style: vivid verbs (emerge, flourish, decline, collapse), noun phrases: the rise and fall of…, the outbreak of…'],
      eg: [['Initially, the town was a small trading post.', 'Dastlab shahar kichik savdo punkti edi.'], ['Meanwhile, merchants were bringing silk from the east.', 'Shu orada savdogarlar sharqdan ipak olib kelardi.'], ['Ultimately, the empire collapsed.', 'Oxir-oqibat imperiya qulab tushdi.'], ['In retrospect, the decision was a mistake.', 'Orqaga nazar tashlasak, qaror xato edi.']],
      w: [['flourish', 'gullab-yashnamoq', 'процветать', 'verb', 'Trade flourished under his rule.', 'Uning hukmronligida savdo gullab-yashnadi.', 'ˈflʌrɪʃ'], ['decline', 'tanazzulga yuz tutmoq', 'приходить в упадок', 'verb', 'The city began to decline.', 'Shahar tanazzulga yuz tuta boshladi.', 'dɪˈklaɪn'], ['collapse', 'qulab tushmoq', 'рухнуть', 'verb', 'The empire collapsed in 1450.', 'Imperiya 1450-yilda qulab tushdi.', 'kəˈlæps'], ['chronology', 'xronologiya', 'хронология', 'noun', 'Follow the chronology of events.', 'Voqealar xronologiyasiga amal qiling.', 'krəˈnɒlədʒi'], ['initially', 'dastlab', 'сначала', 'adverb', 'Initially, nobody believed him.', 'Dastlab hech kim unga ishonmadi.', 'ɪˈnɪʃəli'], ['legacy', 'meros (ta’sir)', 'наследие', 'noun', 'His legacy lives on.', 'Uning merosi yashaydi.', 'ˈleɡəsi']],
      g: [['___, the town was a small trading post.', 'Initially', 'Initial', 'Initiate', 'Ravish kerak.'], ['Meanwhile, merchants ___ silk from the east.', 'were bringing', 'brought', 'had bring', 'Fon — Past Continuous.']],
      dlg: ['Teacher: How do you organise a text about the past? Student: With an introduction, events in chronological order and the legacy. Teacher: Which tenses? Student: Past Simple for main events, Past Continuous for background and Past Perfect for earlier actions. Teacher: Add linkers such as initially and ultimately.', 'Which tense gives background?', 'Past Continuous', 'Past Perfect', 'Present Simple', 'The student says Past Continuous.'],
      rd: ['The Silk Road did not begin as a single road but as a network of trade routes that gradually emerged over centuries. Initially, merchants exchanged goods in short stages, while ideas and religions were travelling with them. Cities such as Samarkand flourished as crossroads of cultures. Ultimately, the discovery of sea routes and political instability caused the land routes to decline. However, the legacy of the Silk Road still shapes the cuisine, architecture and languages of Central Asia.', ['Why did the land routes decline?', 'Sea routes and political instability', 'Floods', 'A lack of silk'], ['The Silk Road was a single road.', 'False'], ['Samarkand was founded by Greeks.', 'Not Given']],
      wr: ['Write a short history (250 words) of a place or event in your country: context, chronology, consequences and legacy.', 'initially|meanwhile|ultimately|legacy', 190, 'The city of Bukhara has a long and fascinating history. Initially, it was a small oasis settlement. Meanwhile, merchants were travelling along the Silk Road and the city began to grow. By the 10th century it had become an important centre of learning. Following this, it flourished under several dynasties. Ultimately, its importance declined, but its legacy remains in its architecture and traditions.'],
      sp: ['Tell the story of a place from your region in chronological order.', 'Initially it was a small village. Later it grew into a city. Its legacy is its beautiful architecture.'],
      ts: [['The lasting influence of the past:', 'legacy', 'chronology', 'reign'], ['“Qulab tushmoq” in English:', 'collapse', 'flourish', 'conquer'], ['___ the town was tiny.', 'Initially', 'Initial', 'Finally of']] },
  ], exam: [['By the time he arrived, they ___ left.', 'had', 'have', 'were', 'grammar'], ['___ in a palace, the museum is huge.', 'Housed', 'Housing', 'To house', 'grammar'], ['A ruler’s period in power:', 'reign', 'treaty', 'uprising', 'vocabulary']] },

  { title: 'Ethics and choices', lessons: [
    { t: ['Ethical dilemmas', 'Axloqiy dilemmalar'],
      obj: ['Axloqiy dilemmalarni muhokama qilib, qarorni asoslaysiz.', 'You will discuss ethical dilemmas and justify decisions.'],
      ex: ['Axloq: ethics, moral (axloqiy), dilemma, integrity (halollik), conscience (vijdon), whistleblower, justice, duty vs consequence. Fikr: It depends on whether… ; On balance, …; What would you do in my position? Gipotetik: If I were in his position, I would… ; Were I to find a wallet, I would return it. Inversion: Were I to…, Had I known… , Should anyone ask,…\nFe’llar: justify (asoslamoq), condemn (qoralamoq), tolerate, take responsibility, weigh up.',  'Ethics: ethics, moral, dilemma, integrity, conscience, whistleblower, justice, duty vs consequence. Opinion: It depends on whether… ; On balance, …; What would you do in my position? Hypothetical: If I were in his position, I would… ; Were I to find a wallet, I would return it. Inversion: Were I to…, Had I known…, Should anyone ask,…\nVerbs: justify, condemn, tolerate, take responsibility, weigh up.'],
      eg: [['Were I to find a wallet, I would return it.', 'Hamyon topsam, uni qaytarar edim.'], ['If I were in his position, I would tell the truth.', 'Uning o‘rnida bo‘lsam, haqiqatni aytardim.'], ['On balance, honesty is more important than loyalty.', 'Umuman olganda, halollik sadoqatdan muhimroq.'], ['Whistleblowers take a great personal risk.', 'Ogohlantiruvchilar katta shaxsiy xavf qilishadi.']],
      w: [['dilemma', 'dilemma', 'дилемма', 'noun', 'It was a difficult dilemma.', 'Bu qiyin dilemma edi.', 'dɪˈlemə'], ['integrity', 'halollik, to‘g‘rilik', 'честность', 'noun', 'He is a person of integrity.', 'U halol inson.', 'ɪnˈteɡrəti'], ['conscience', 'vijdon', 'совесть', 'noun', 'My conscience is clear.', 'Vijdonim toza.', 'ˈkɒnʃəns'], ['whistleblower', 'ogohlantiruvchi (xabar beruvchi)', 'информатор', 'noun', 'The whistleblower reported fraud.', 'Xabar beruvchi firibgarlikni xabar qildi.', 'ˈwɪslbləʊə'], ['justify', 'asoslamoq', 'оправдывать', 'verb', 'How can you justify lying?', 'Yolg‘on gapirishni qanday asoslaysiz?', 'ˈdʒʌstɪfaɪ'], ['condemn', 'qoralamoq', 'осуждать', 'verb', 'Many condemned the decision.', 'Ko‘pchilik qarorni qoraladi.', 'kənˈdem']],
      g: [['___ I to find a wallet, I would return it.', 'Were', 'Was', 'Had', 'Inversiya: Were I to...'], ['If I ___ in his position, I would tell the truth.', 'were', 'am', 'was being', 'Second conditional.']],
      dlg: ['Teacher: You see a colleague cheating on a report. What do you do? Student: It depends on whether it harms others. Teacher: Suppose it does. Student: Were I to stay silent, my conscience would trouble me. I would report it. Teacher: Even if it costs your job? Student: On balance, integrity matters more.', 'What would the student do?', 'Report the cheating', 'Stay silent', 'Leave the job', 'She says “I would report it”.'],
      rd: ['An ethical dilemma arises when a person must choose between two actions, each of which has moral costs. A classic example is the whistleblower who discovers wrongdoing in their own company. Staying silent protects a job but may harm the public; speaking out protects the public but risks one’s career. Philosophers disagree on how to decide: some focus on duty and principle, others on the consequences of each choice. Most people, in practice, weigh up both.', ['What do most people do in practice?', 'Weigh up both principles and consequences', 'Follow only the law', 'Ignore dilemmas'], ['Philosophers all agree on one method.', 'False'], ['Whistleblowers are always rewarded.', 'Not Given']],
      wr: ['Describe a moral dilemma (invented) and explain what you would do and why (10–12 sentences).', 'were i to|if i were|on balance|conscience', 80, 'Imagine you see a colleague copying a report. It is a difficult dilemma. If I were in that position, I would talk to him first. Were I to find that nothing changed, I would inform my manager. On balance, integrity is more important than friendship. My conscience would not allow me to stay silent.'],
      sp: ['You find a wallet with money. What do you do and why?', 'I would return it. Were I to keep it, my conscience would trouble me.'],
      ts: [['A person who exposes wrongdoing:', 'whistleblower', 'dilemma', 'conscience'], ['“Vijdon” in English:', 'conscience', 'integrity', 'justice'], ['___ I known, I would have helped.', 'Had', 'Were', 'Should']] },
    { t: ['Second and third conditionals', 'Ikkinchi va uchinchi shartli gaplar'],
      obj: ['Ikkinchi, uchinchi va aralash shartli gaplarni aniq qo‘llaysiz.', 'You will use the second, third and mixed conditionals accurately.'],
      ex: ['2-shartli: If + Past Simple, would + fe’l — hozir/kelajakdagi xayoliy: If I had more time, I would travel. 3-shartli: If + Past Perfect, would have + V3 — o‘tgan, o‘zgartirib bo‘lmaydigan: If I had studied, I would have passed. Aralash: If I had taken the job, I would be rich now.\nO‘rniga: unless, provided that, as long as, otherwise, but for (… bo‘lmaganda): But for your help, I would have failed. “I wish / if only” + Past Perfect: I wish I had listened. Inversion: Had I known, I would have called.', '2nd conditional: If + Past Simple, would + verb — imaginary present/future: If I had more time, I would travel. 3rd conditional: If + Past Perfect, would have + V3 — unreal past: If I had studied, I would have passed. Mixed: If I had taken the job, I would be rich now.\nAlternatives: unless, provided that, as long as, otherwise, but for: But for your help, I would have failed. “I wish / if only” + Past Perfect: I wish I had listened. Inversion: Had I known, I would have called.'],
      eg: [['If I had more time, I would travel the world.', 'Ko‘proq vaqtim bo‘lsa, dunyo bo‘ylab sayohat qilardim.'], ['If I had studied, I would have passed the exam.', 'O‘qiganimda, imtihondan o‘tgan bo‘lardim.'], ['But for your help, I would have failed.', 'Yordamingiz bo‘lmaganida, yiqilgan bo‘lardim.'], ['I wish I had listened to my parents.', 'Kashki ota-onamni tinglaganimda.']],
      w: [['regret', 'afsuslanmoq', 'сожалеть', 'verb', 'I regret not studying.', 'O‘qimaganimga afsuslanaman.', 'rɪˈɡret'], ['hypothetical', 'taxminiy', 'гипотетический', 'adjective', 'It is a hypothetical situation.', 'Bu taxminiy vaziyat.', 'ˌhaɪpəˈθetɪkl'], ['otherwise', 'aks holda', 'иначе', 'adverb', 'Hurry, otherwise you will miss it.', 'Shoshiling, aks holda ulgurmaysiz.', 'ˈʌðəwaɪz'], ['outcome', 'natija', 'исход', 'noun', 'The outcome would have been different.', 'Natija boshqacha bo‘lardi.', 'ˈaʊtkʌm'], ['circumstances', 'sharoit', 'обстоятельства', 'noun', 'In different circumstances, I would agree.', 'Boshqa sharoitda rozi bo‘lardim.', 'ˈsɜːkəmstənsɪz'], ['imagine', 'tasavvur qilmoq', 'представлять', 'verb', 'Imagine you won a prize.', 'Sovrin yutganingizni tasavvur qiling.', 'ɪˈmædʒɪn']],
      g: [['If I ___ studied, I would have passed.', 'had', 'have', 'would have', '3-shartli: if + Past Perfect.'], ['But ___ your help, I would have failed.', 'for', 'to', 'of', '“But for” — … bo‘lmaganida.']],
      dlg: ['Anna: Do you have any regrets? Ali: If I had studied harder at school, I would have got into a better university. Anna: Would you be doing a different job now? Ali: Yes, if I had taken that course, I would be an engineer today. Anna: But for your experience, you wouldn’t be so wise.', 'What would Ali be if he had taken the course?', 'An engineer', 'A teacher', 'A doctor', 'He says “I would be an engineer today”.'],
      rd: ['Psychologists call imagining how the past might have been different “counterfactual thinking”. When people reflect on missed chances, they often use the third conditional: “If I had applied, I would have got the job.” Such thoughts can cause regret, but they can also be useful, since they help people learn from mistakes and prepare better in future. The danger arises when someone dwells on hypothetical outcomes and cannot accept present circumstances.', ['When can counterfactual thinking be useful?', 'When it helps people learn from mistakes', 'When it increases regret', 'When it replaces action'], ['Counterfactual thinking is always harmful.', 'False'], ['Counterfactual thinking was discovered in 1990.', 'Not Given']],
      wr: ['Write 10 sentences about regrets and imaginary situations using second, third and mixed conditionals.', 'if i had|would have|if i were|but for', 70, 'If I had studied harder at school, I would have got into a better university. If I had more free time, I would learn another language. But for my teacher’s advice, I would have failed. If I had taken that course, I would be working abroad now. I wish I had listened to my parents.'],
      sp: ['Say what you would do if you won a lot of money, and one thing you would have done differently in the past.', 'If I won a lot of money, I would travel. If I had studied harder, I would have gone to a better university.'],
      ts: [['Unreal past: If + ?', 'Past Perfect', 'Past Simple', 'Present Simple'], ['“Aks holda” in English:', 'otherwise', 'outcome', 'regret'], ['If I ___ rich, I would travel.', 'were', 'had been', 'will be']] },
    { t: ['Passive and reporting structures', 'Majhul va hisobot tuzilmalari'],
      obj: ['Majhul nisbat va xabar berish tuzilmalarini rasmiy matnlarda qo‘llaysiz.', 'You will use passive and reporting structures in formal texts.'],
      ex: ['Majhul turlari: Present Perfect Passive (has been done), Modal Passive (must be done), Future Passive (will be completed), Continuous Passive (is being built). Maqsad: ma’lum bo‘lmagan/muhim emas bajaruvchini yashirish; rasmiy uslub.\nHisobot tuzilmalari: It is said/believed/reported/thought that… = He is said to be… = He is said to have been… (o‘tgan). They are expected to…, It has been suggested that… Bayon qilingan nutq: She asked whether I was ready; He suggested going; They insisted on paying. Causative: have something done: I had my hair cut.', 'Passive forms: Present Perfect Passive (has been done), Modal Passive (must be done), Future Passive (will be completed), Continuous Passive (is being built). Use: the agent is unknown/unimportant; formal style.\nReporting structures: It is said/believed/reported/thought that… = He is said to be… = He is said to have been… (past). They are expected to…, It has been suggested that… Reported speech: She asked whether I was ready; He suggested going; They insisted on paying. Causative: have something done: I had my hair cut.'],
      eg: [['The bridge is being repaired at the moment.', 'Ko‘prik hozir ta’mirlanmoqda.'], ['The report must be submitted by Friday.', 'Hisobot juma kuniga qadar topshirilishi kerak.'], ['He is said to have been a brilliant student.', 'U a’lo talaba bo‘lgani aytiladi.'], ['I had my car repaired last week.', 'O‘tgan hafta mashinamni ta’mirlatdim.']],
      w: [['submit', 'topshirmoq', 'подавать', 'verb', 'Submit your essay online.', 'Esseni onlayn topshiring.', 'səbˈmɪt'], ['expected', 'kutilmoqda', 'ожидаемый', 'adjective', 'He is expected to arrive soon.', 'Uning tez orada kelishi kutilmoqda.', 'ɪkˈspektɪd'], ['insist', 'turib olmoq', 'настаивать', 'verb', 'She insisted on paying.', 'U to‘lashga turib oldi.', 'ɪnˈsɪst'], ['suggest', 'taklif qilmoq', 'предлагать', 'verb', 'He suggested going home.', 'U uyga ketishni taklif qildi.', 'səˈdʒest'], ['repair', 'ta’mirlamoq', 'ремонтировать', 'verb', 'We repaired the roof.', 'Biz tomni ta’mirladik.', 'rɪˈpeə'], ['agent', 'bajaruvchi', 'исполнитель', 'noun', 'The agent of the action is unknown.', 'Harakat bajaruvchisi noma’lum.', 'ˈeɪdʒənt']],
      g: [['The bridge ___ repaired at the moment.', 'is being', 'is', 'has', 'Continuous Passive.'], ['He is said ___ been a brilliant student.', 'to have', 'having', 'that he', 'Ma’lum o‘tgan: to have been.']],
      dlg: ['Editor: Is the report finished? Reporter: It must be submitted by Friday, and it is being checked now. Editor: The mayor is said to have changed his mind. Reporter: It has been suggested that he was pressured. Editor: He insisted on denying it. Reporter: We should have our facts verified before publishing.', 'What is being done to the report now?', 'It is being checked', 'It is being printed', 'It is being sold', 'The reporter says “it is being checked now”.'],
      rd: ['Formal writing often uses passive and reporting structures to sound objective. Instead of “People believe that the project failed”, a writer may say “The project is believed to have failed”. Passive forms are common in scientific reports, news and instructions because the agent is either unknown or unimportant. Careful writers, however, avoid overusing the passive, since too many passive sentences can make a text heavy and unclear. A good rule is to use it when the action or result is more important than the person who did it.', ['When is the passive most useful?', 'When the action is more important than the doer', 'In every sentence', 'In informal chat only'], ['Passive sentences always make writing clearer.', 'False'], ['The passive was invented by scientists.', 'Not Given']],
      wr: ['Rewrite 6 active sentences into passive/reporting structures and add 4 original sentences about a news event.', 'is said to|has been|must be|being', 70, 'The project is believed to have failed. The report must be submitted by Friday. The bridge is being repaired. He is said to have been a brilliant student. The results have been published. It has been suggested that the law should be changed.'],
      sp: ['Report a piece of news using “is said to” and “has been”.', 'The mayor is said to have changed his plans. A new bridge has been built.'],
      ts: [['Passive: “They are building a house.”', 'A house is being built.', 'A house builds.', 'A house was build.'], ['“Topshirmoq” in English:', 'submit', 'insist', 'expect'], ['She insisted ___ paying.', 'on', 'to', 'at']] },
    { t: ['B2 review: argument and style', 'B2 takrorlash: dalil va uslub'],
      obj: ['B2 mavzularini yakuniy takrorlab, dalilli va uslubi aniq matn yozasiz.', 'You will review B2 topics and write a well-argued, stylistically accurate text.'],
      ex: ['Takrorlash: murakkab gaplar (relative, participle, inversion), shartli aralash (2,3, mixed), majhul va hisobot tuzilmalari, hedging, bog‘lovchilar, kollokatsiyalar. Dalil uslubi: Thesis → Evidence → Analysis → Counter-argument → Link. Uslub: formal register, nominalisation (otlashtirish): “People are poorer” → “Poverty has increased”. Aniq lug‘at: a significant increase (not “a big increase”).\nO‘z-o‘zini tekshirish ro‘yxati: 1) Thesis aniq? 2) Har paragrafda bitta g‘oya? 3) Linkerlar xilma-xilmi? 4) Qisqartma yo‘qmi? 5) Takrorlanuvchi so‘z yo‘qmi?', 'Review: complex sentences (relative, participle, inversion), mixed conditionals, passive and reporting structures, hedging, linkers, collocations. Argument style: Thesis → Evidence → Analysis → Counter-argument → Link. Style: formal register, nominalisation (“People are poorer” → “Poverty has increased”). Precise lexis: a significant increase (not “a big increase”).\nSelf-check list: 1) Is the thesis clear? 2) One idea per paragraph? 3) Varied linkers? 4) No contractions? 5) No repeated words?'],
      eg: [['Poverty has increased significantly in recent years.', 'So‘nggi yillarda qashshoqlik sezilarli oshdi.'], ['Had governments acted earlier, the damage would have been limited.', 'Hukumatlar erta harakat qilganida, zarar cheklangan bo‘lardi.'], ['It is widely believed that education reduces inequality.', 'Ta’lim tengsizlikni kamaytirishi keng e’tirof etiladi.'], ['Whilst technology is beneficial, it must be used responsibly.', 'Texnologiya foydali bo‘lsa-da, mas’uliyat bilan ishlatilishi kerak.']],
      w: [['nominalisation', 'otlashtirish', 'номинализация', 'noun', 'Nominalisation makes writing formal.', 'Otlashtirish yozuvni rasmiy qiladi.', 'ˌnɒmɪnəlaɪˈzeɪʃn'], ['register', 'uslub darajasi', 'регистр речи', 'noun', 'Use a formal register in essays.', 'Esselarda rasmiy uslubdan foydalaning.', 'ˈredʒɪstə'], ['significant', 'sezilarli', 'значительный', 'adjective', 'There was a significant rise.', 'Sezilarli o‘sish bo‘ldi.', 'sɪɡˈnɪfɪkənt'], ['analysis', 'tahlil', 'анализ', 'noun', 'Your analysis is thorough.', 'Tahlilingiz puxta.', 'əˈnæləsɪs'], ['coherent', 'izchil', 'связный', 'adjective', 'A coherent text flows logically.', 'Izchil matn mantiqan oqadi.', 'kəʊˈhɪərənt'], ['revise', 'qayta ko‘rib chiqmoq', 'редактировать', 'verb', 'Revise your draft carefully.', 'Qoralamani sinchiklab qayta ko‘rib chiqing.', 'rɪˈvaɪz']],
      g: [['___ governments acted earlier, the damage would have been limited. (inversion)', 'Had', 'If had', 'Have', 'Third conditional inversiya.'], ['It ___ widely believed that education reduces inequality.', 'is', 'are', 'does', 'Majhul.']],
      dlg: ['Tutor: Check your essay with this list: is the thesis clear? Student: Yes. Tutor: Do you have varied linkers and no contractions? Student: I replaced “big increase” with “significant increase”. Tutor: Good. Is it coherent? Student: I revised the order of my paragraphs.', 'What did the student replace?', '“big increase” with “significant increase”', '“thesis” with “idea”', '“essay” with “text”', 'The student says so.'],
      rd: ['A strong B2 text does not simply list opinions; it builds an argument. The writer states a clear position, supports it with evidence, analyses why that evidence matters and addresses a possible counter-argument. The style is formal and precise, with varied linkers and accurate complex structures. After writing, successful students revise their work, checking coherence, vocabulary and grammar. Many learners improve most quickly by comparing their first draft with a revised one.', ['How do many learners improve most quickly?', 'By comparing first and revised drafts', 'By writing less', 'By avoiding feedback'], ['A strong text only lists opinions.', 'False'], ['The writer is an examiner.', 'Not Given']],
      wr: ['Write a final argumentative essay (250–280 words) on any B2 topic of your choice. Use a thesis, evidence, a counter-argument, hedging and a conclusion.', 'it is widely believed|whilst|had|in conclusion', 190, 'It is widely believed that technology improves education. This essay will argue that, when used wisely, it does. Firstly, a growing body of evidence suggests that online resources make learning accessible. Whilst some claim that screens are distracting, teachers who set clear rules usually find that the benefits outweigh the risks. Had schools ignored technology, many students would have lost access to learning during emergencies. In conclusion, technology is a valuable tool whose success depends on responsible use.'],
      sp: ['Speak for two minutes: present a thesis, two arguments and a counter-argument on a topic of your choice.', 'I believe that education reduces inequality. First, it gives equal chances. Second, it raises incomes. Critics say it is expensive, but the benefits outweigh the cost.'],
      ts: [['Using formal vs informal language is about:', 'register', 'framing', 'regret'], ['“Izchil” in English:', 'coherent', 'significant', 'hypothetical'], ['___ I known, I would have helped.', 'Had', 'If had', 'Have']] },
  ], exam: [['The new bridge ___ built at the moment.', 'is being', 'is', 'has', 'grammar'], ['If I ___ harder, I would have passed.', 'had studied', 'studied', 'would study', 'grammar'], ['“Dilemma” means a difficult:', 'choice', 'recipe', 'holiday', 'vocabulary']] },
];
